import json, sys

def send(msg):
    sys.stdout.write(json.dumps(msg) + '\n')
    sys.stdout.flush()

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    msg = json.loads(line)
    if 'id' not in msg:
        continue
    if msg.get('method') == 'initialize':
        result = {'protocolVersion': '2025-06-18', 'capabilities': {'tools': {}}, 'serverInfo': {'name': 'fake', 'version': '1'}}
    elif msg.get('method') == 'tools/list':
        result = {'tools': [{'name': 'echo', 'description': 'echo back', 'inputSchema': {'type': 'object', 'properties': {'message': {'type': 'string'}}}}]}
    elif msg.get('method') == 'tools/call':
        m = msg['params']['arguments'].get('message', '')
        result = {'content': [{'type': 'text', 'text': 'echo: ' + m}]}
    else:
        send({'jsonrpc': '2.0', 'id': msg['id'], 'error': {'code': -32601, 'message': 'no such method'}})
        continue
    send({'jsonrpc': '2.0', 'id': msg['id'], 'result': result})
